pragma language_version >= 0.20;
import CompactStandardLibrary;

// Bit flags as Vector<8, Boolean>: &, |, ^, ~ become &&, ||, !=, ! applied with map.
export pure circuit andFlags(a: Vector<8, Boolean>, b: Vector<8, Boolean>): Vector<8, Boolean> {
  return map((x, y) => x && y, a, b);
}

export pure circuit orFlags(a: Vector<8, Boolean>, b: Vector<8, Boolean>): Vector<8, Boolean> {
  return map((x, y) => x || y, a, b);
}

export pure circuit xorFlags(a: Vector<8, Boolean>, b: Vector<8, Boolean>): Vector<8, Boolean> {
  return map((x, y) => x != y, a, b);
}

export pure circuit notFlags(a: Vector<8, Boolean>): Vector<8, Boolean> {
  return map((x) => !x, a);
}

