right3.compact.source:
pragma language_version >= 0.20;
import CompactStandardLibrary;

// a >> 3: the witness supplies quotient and remainder, the circuit checks them.
witness shiftRight3(a: Uint<8>): [Uint<8>, Uint<8>];

export circuit f(a: Uint<8>): Uint<8> {
  const qr = shiftRight3(a);
  const q = qr[0];
  const r = qr[1];
  assert(r < 8, "remainder out of range");
  assert(q * 8 + r == a, "bad quotient");
  return disclose(q);
}

