import CompactStandardLibrary;
circuit neg(p: JubjubPoint): JubjubPoint {
  return constructJubjubPoint(0 - jubjubPointX(p), jubjubPointY(p));
}
export circuit cancels(k: Field): Boolean {
  const p = ecMulGenerator(k);
  return disclose(ecAdd(p, neg(p)) == ecMulGenerator(0));
}
export circuit doubles(k: Field): Boolean {
  const p = ecMulGenerator(k);
  return disclose(ecAdd(p, p) == ecMulGenerator(0));
}
export circuit involution(k: Field): Boolean {
  const p = ecMulGenerator(k);
  return disclose(neg(neg(p)) == p && neg(p) != p);
}

