pragma language_version >= 0.20;
import CompactStandardLibrary;

// Runtime probe (not a harness case file): EVM-style running total kept in Uint<248>.
// total + x on two Uint<248> is a compile error on 0.31.1 ("resulting value might exceed largest
// representable Uint value (for Field semantics, cast either operand to Field)"), so add goes through Field.
export ledger total: Uint<248>;

export circuit add(x: Uint<248>): [] {
  total = disclose(((total as Field) + x) as Uint<248>);
}

export circuit sub(x: Uint<248>): [] {
  total = disclose(total - x);
}

